<script setup lang="ts">
import { computed, onUnmounted, ref } from 'vue'
import AppIcon from '../components/AppIcon.vue'
import { kindLabels, statusLabels, type DemoTask } from '../lib/model'
import { cancelTask, openTaskResult, tasks } from '../lib/workbench'
const kind = ref('all'), status = ref('all'), detail = ref<DemoTask | null>(null), refreshedAt = ref(''), now = ref(Date.now()), closeButton = ref<HTMLButtonElement>()
let priorFocus: HTMLElement | null = null
const ticker = setInterval(() => { now.value = Date.now() }, 1000)
onUnmounted(() => { clearInterval(ticker) })
const filtered = computed(() => tasks.filter(t => (kind.value === 'all' || t.kind === kind.value) && (status.value === 'all' || t.status === status.value)))
const duration = (task: DemoTask) => `${(((task.endedAt ?? now.value) - task.startedAt) / 1000).toFixed(1)} s`
function show(task: DemoTask) { priorFocus = document.activeElement as HTMLElement; detail.value = task; setTimeout(() => closeButton.value?.focus(), 0) }
function close() { detail.value = null; priorFocus?.focus() }
function trap(event: KeyboardEvent) { if (event.key === 'Escape') { close(); return }; if (event.key !== 'Tab') return; const buttons = Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('button:not(:disabled)')); if (event.shiftKey && document.activeElement === buttons[0]) { buttons[buttons.length - 1]?.focus(); event.preventDefault() } else if (!event.shiftKey && document.activeElement === buttons[buttons.length - 1]) { buttons[0]?.focus(); event.preventDefault() } }
</script>
<template><div class="jobs-page"><div class="metrics-row"><div class="panel metric"><span>本次任务</span><strong>{{ tasks.length.toString().padStart(2,'0') }}</strong></div><div class="panel metric"><span>演示已完成</span><strong>{{ tasks.filter(t => t.status === 'completed').length.toString().padStart(2,'0') }}</strong></div><div class="panel metric"><span>演示运行中</span><strong>{{ tasks.filter(t => t.status === 'running').length.toString().padStart(2,'0') }}</strong></div></div><section class="panel jobs-panel"><div class="jobs-toolbar"><div class="filter-group"><label>类型<select v-model="kind" aria-label="任务类型筛选"><option value="all">全部类型</option><option v-for="(label,id) in kindLabels" :key="id" :value="id">{{ label }}</option></select></label><label>状态<select v-model="status" aria-label="任务状态筛选"><option value="all">全部状态</option><option v-for="(label,id) in statusLabels" :key="id" :value="id">{{ label }}</option></select></label></div><button class="btn" @click="now = Date.now(); refreshedAt = new Date().toLocaleTimeString('zh-CN')"><AppIcon name="refresh" :size="15" />刷新记录</button></div><p v-if="refreshedAt" class="refresh-note" role="status">已刷新记录 · {{ refreshedAt }}</p>
    <div v-if="!filtered.length" class="empty-state jobs-empty"><div class="empty-icon"><AppIcon name="jobs" :size="36" /></div><h3>{{ tasks.length ? '没有符合条件的任务' : '暂无任务' }}</h3><p>{{ tasks.length ? '请调整筛选条件。' : '生成单次、批量或扫描后显示记录。' }}</p><p class="hint">重启应用后清空记录</p></div>
    <div v-else class="table-scroll"><table><thead><tr><th>演示任务 / 时间</th><th>类型</th><th>参数摘要</th><th>状态</th><th>耗时</th><th>操作</th></tr></thead><tbody><tr v-for="task in filtered" :key="task.id"><td><span class="code task-id">{{ task.id }}</span><small class="table-time">{{ new Date(task.startedAt).toLocaleTimeString('zh-CN') }}</small></td><td>{{ kindLabels[task.kind] }}</td><td class="task-summary">{{ task.summary }}</td><td><span :class="['badge', 'task-' + task.status]">{{ statusLabels[task.status] }}</span><small v-if="task.status === 'running'" class="table-time mono">{{ task.progress }}%</small></td><td class="mono">{{ duration(task) }}</td><td><button class="btn sm" @click="show(task)">详情<AppIcon name="chevron" :size="13" /></button></td></tr></tbody></table></div><div class="jobs-footnote"><span>示意任务，非真实计算历史</span></div>
  </section><Transition name="drawer"><div v-if="detail" class="modal-backdrop" @click.self="close"><section class="detail-drawer" role="dialog" aria-modal="true" aria-labelledby="task-detail-title" @keydown="trap"><div class="panel-heading"><h2 id="task-detail-title">演示任务详情</h2><button ref="closeButton" class="icon-btn" aria-label="关闭任务详情" @click="close"><AppIcon name="close" /></button></div><span :class="['badge', 'task-' + detail.status]">{{ statusLabels[detail.status] }}</span><dl class="detail-list"><dt>任务 ID</dt><dd class="code">{{ detail.id }}</dd><dt>类型</dt><dd>{{ kindLabels[detail.kind] }} · 界面演示</dd><dt>参数摘要</dt><dd>{{ detail.summary }}</dd><dt>开始时间</dt><dd>{{ new Date(detail.startedAt).toLocaleString('zh-CN') }}</dd><dt>实际界面耗时</dt><dd class="mono">{{ duration(detail) }}</dd><template v-if="detail.detail"><dt>状态说明</dt><dd>{{ detail.detail }}</dd></template><dt>来源</dt><dd class="code">frontend_demo / illustrative</dd></dl><button v-if="detail.status === 'running'" class="btn danger full" @click="cancelTask(detail)">取消任务</button><button v-if="detail.status === 'completed'" class="btn primary full" @click="openTaskResult(detail); close()">查看结果<AppIcon name="arrow" :size="16" /></button><div class="backend-action"><button class="btn" disabled>打开真实结果目录</button><p class="hint">连接引擎后可用</p></div></section></div></Transition></div></template>
